package com.airesumebuilder.feature.ats.controller;
import com.airesumebuilder.common.dto.ApiResponse;import com.airesumebuilder.feature.ats.service.AtsService;import com.airesumebuilder.security.CurrentUser;import jakarta.validation.Valid;import java.util.List;import org.springframework.http.*;import org.springframework.web.bind.annotation.*;
@RestController@RequestMapping("/api/v1/ats")public class AtsController{private final AtsService service;private final CurrentUser user;public AtsController(AtsService s,CurrentUser u){service=s;user=u;}@GetMapping("/health")public ResponseEntity<ApiResponse<String>>health(){return ResponseEntity.ok(ApiResponse.success("UP","ATS service is available."));}@PostMapping("/analyze")public ResponseEntity<ApiResponse<AtsService.Report>>analyze(@Valid@RequestBody AtsService.AnalyzeRequest r){return ResponseEntity.status(HttpStatus.CREATED).body(ApiResponse.success(service.analyze(user.email(),r),"ATS analysis completed."));}@GetMapping("/reports/{id}")public ResponseEntity<ApiResponse<AtsService.Report>>get(@PathVariable long id){return ResponseEntity.ok(ApiResponse.success(service.get(user.email(),id),"ATS report retrieved."));}@GetMapping("/resumes/{resumeId}/reports")public ResponseEntity<ApiResponse<List<AtsService.ReportSummary>>>list(@PathVariable long resumeId){return ResponseEntity.ok(ApiResponse.success(service.list(user.email(),resumeId),"ATS reports retrieved."));}}
